CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE source_ingestion_jobs(id UUID PRIMARY KEY,source_type TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,submitted_by UUID,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE source_versions(id UUID PRIMARY KEY,source_id UUID NOT NULL,version_label TEXT NOT NULL,checksum TEXT NOT NULL,content_uri TEXT,review_status TEXT DEFAULT 'DRAFT',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE source_review_history(id UUID PRIMARY KEY,source_version_id UUID NOT NULL,reviewer_id UUID NOT NULL,decision TEXT NOT NULL,notes TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE abdul_agents(id UUID PRIMARY KEY,agent_key TEXT UNIQUE NOT NULL,name TEXT NOT NULL,enabled BOOLEAN DEFAULT true,policy JSONB DEFAULT '{}');
CREATE TABLE abdul_tasks(id UUID PRIMARY KEY,session_id UUID,task_type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'QUEUED',agent_plan JSONB NOT NULL,source_ids JSONB DEFAULT '[]',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE graph_clusters(id UUID PRIMARY KEY,slug TEXT UNIQUE NOT NULL,label TEXT NOT NULL,description TEXT,review_status TEXT DEFAULT 'DRAFT');
CREATE TABLE graph_metrics(id UUID PRIMARY KEY,node_id UUID NOT NULL,degree_score REAL DEFAULT 0,evidence_score REAL DEFAULT 0,updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE research_projects(id UUID PRIMARY KEY,owner_user_id UUID NOT NULL,title TEXT NOT NULL,description TEXT,visibility TEXT DEFAULT 'PRIVATE',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE project_members(project_id UUID NOT NULL,user_id UUID NOT NULL,role TEXT NOT NULL,PRIMARY KEY(project_id,user_id));
CREATE TABLE project_sources(project_id UUID NOT NULL,source_id UUID NOT NULL,annotation TEXT,PRIMARY KEY(project_id,source_id));
CREATE TABLE learning_tracks(id UUID PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT,status TEXT DEFAULT 'DRAFT');
CREATE TABLE learning_programs(id UUID PRIMARY KEY,track_id UUID NOT NULL,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,status TEXT DEFAULT 'DRAFT');
CREATE TABLE certificates(id UUID PRIMARY KEY,user_id UUID NOT NULL,program_id UUID NOT NULL,verification_code TEXT UNIQUE NOT NULL,issued_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE communities(id UUID PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,community_type TEXT NOT NULL,status TEXT DEFAULT 'PENDING');
CREATE TABLE community_members(community_id UUID NOT NULL,user_id UUID NOT NULL,role TEXT DEFAULT 'MEMBER',status TEXT DEFAULT 'PENDING',PRIMARY KEY(community_id,user_id));
CREATE TABLE community_reports(id UUID PRIMARY KEY,community_id UUID NOT NULL,reporter_user_id UUID,reason TEXT NOT NULL,status TEXT DEFAULT 'OPEN',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE api_keys(id UUID PRIMARY KEY,owner_user_id UUID NOT NULL,name TEXT NOT NULL,prefix TEXT UNIQUE NOT NULL,key_hash TEXT NOT NULL,scopes TEXT[] DEFAULT '{}',enabled BOOLEAN DEFAULT true,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE api_usage(id UUID PRIMARY KEY,api_key_id UUID NOT NULL,route TEXT NOT NULL,status_code INTEGER NOT NULL,request_units INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE analytics_rollups(id UUID PRIMARY KEY,metric_date DATE NOT NULL,metric_name TEXT NOT NULL,dimension JSONB DEFAULT '{}',metric_value NUMERIC NOT NULL,UNIQUE(metric_date,metric_name,dimension));


-- SAFE COMMUNITY, Q&A, EVENTS AND MULTI-STAGE REVIEW
CREATE TABLE discussion_spaces(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,description TEXT,space_type TEXT NOT NULL CHECK(space_type IN('COMMUNITY','STUDY_CIRCLE','Q_AND_A','EVENT_SESSION')),status TEXT NOT NULL DEFAULT 'PENDING',moderation_policy JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE discussion_members(space_id UUID NOT NULL,user_id UUID NOT NULL,role TEXT NOT NULL DEFAULT 'MEMBER',status TEXT NOT NULL DEFAULT 'ACTIVE',joined_at TIMESTAMPTZ DEFAULT now(),PRIMARY KEY(space_id,user_id));
CREATE TABLE discussion_threads(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),space_id UUID NOT NULL REFERENCES discussion_spaces(id) ON DELETE CASCADE,author_id UUID NOT NULL,title TEXT NOT NULL,thread_type TEXT NOT NULL DEFAULT 'DISCUSSION',status TEXT NOT NULL DEFAULT 'PENDING_REVIEW',locked BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE discussion_posts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),thread_id UUID NOT NULL REFERENCES discussion_threads(id) ON DELETE CASCADE,author_id UUID NOT NULL,parent_post_id UUID REFERENCES discussion_posts(id) ON DELETE CASCADE,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_REVIEW',moderation JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE questions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),author_id UUID NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_REVIEW',accepted_answer_id UUID,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE answers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE,author_id UUID NOT NULL,body TEXT NOT NULL,source_links JSONB NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'PENDING_REVIEW',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE interactive_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,description TEXT,facilitator_id UUID,start_at TIMESTAMPTZ,end_at TIMESTAMPTZ,language TEXT DEFAULT 'en',status TEXT NOT NULL DEFAULT 'DRAFT',recording_policy TEXT DEFAULT 'NO_RECORDING',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE islamic_calendar_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,event_type TEXT NOT NULL,gregorian_start DATE,gregorian_end DATE,hijri_month INTEGER,hijri_day INTEGER,location_scope TEXT DEFAULT 'GLOBAL',description TEXT,source_notes JSONB NOT NULL DEFAULT '[]',review_status TEXT NOT NULL DEFAULT 'DRAFT',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE moderation_cases(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL,entity_id UUID NOT NULL,reason_codes TEXT[] NOT NULL DEFAULT '{}',risk_level TEXT NOT NULL,decision TEXT NOT NULL DEFAULT 'REVIEW',reviewer_id UUID,notes TEXT,created_at TIMESTAMPTZ DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE guardrail_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL,entity_id UUID,stage TEXT NOT NULL,agent_key TEXT NOT NULL,input_hash TEXT,decision TEXT NOT NULL,reasons JSONB NOT NULL DEFAULT '[]',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE fact_check_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),entity_type TEXT NOT NULL,entity_id UUID NOT NULL,source_coverage REAL NOT NULL DEFAULT 0,citation_count INTEGER NOT NULL DEFAULT 0,unsupported_claims INTEGER NOT NULL DEFAULT 0,decision TEXT NOT NULL DEFAULT 'REVIEW',created_at TIMESTAMPTZ DEFAULT now());
